CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE "passkeys" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "credential_id" varchar not null, "credential" text not null, "last_used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE INDEX "passkeys_user_id_index" on "passkeys" ("user_id");
CREATE UNIQUE INDEX "passkeys_credential_id_unique" on "passkeys" ("credential_id");
CREATE TABLE "restaurants" ("id" integer primary key autoincrement not null, "name" varchar not null, "address" varchar not null, "phone_number" varchar not null, "nif" varchar not null, "status" varchar check ("status" in ('active', 'inactive')) not null default 'active', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "restaurants_nif_unique" on "restaurants" ("nif");
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "restaurant_id" integer, "address" varchar, "contact" varchar, "nif" varchar, "status" varchar check ("status" in ('active', 'inactive')) not null default 'active', "role" varchar not null default 'customer', foreign key("restaurant_id") references "restaurants"("id"));
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE "order_itens" ("id" integer primary key autoincrement not null, "product_id" integer not null, "value" numeric not null, "created_at" datetime, "updated_at" datetime, "order_id" integer not null, "quantity" integer not null default '1', foreign key("product_id") references "produts"("id") on delete no action on update no action, foreign key("order_id") references "orders"("id"));
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "status" varchar not null default ('active'), "created_at" datetime, "updated_at" datetime, "restaurant_id" integer, foreign key("restaurant_id") references "restaurants"("id") on delete restrict);
CREATE TABLE "produts" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "price" numeric not null, "quantity" integer not null, "category_id" integer not null, "status" varchar not null default ('active'), "created_at" datetime, "updated_at" datetime, "restaurant_id" integer, foreign key("category_id") references "categories"("id") on delete no action on update no action, foreign key("restaurant_id") references "restaurants"("id") on delete restrict);
CREATE TABLE "orders" ("id" integer primary key autoincrement not null, "payment_status" varchar not null default ('pending'), "payment_value" numeric not null default ('0'), "customer_id" integer not null, "user_id" integer not null, "address" varchar not null, "delivery_date" date not null, "created_at" datetime, "updated_at" datetime, "restaurant_id" integer, foreign key("user_id") references "users"("id") on delete no action on update no action, foreign key("customer_id") references "users"("id") on delete no action on update no action, foreign key("restaurant_id") references "restaurants"("id") on delete restrict);
CREATE INDEX "users_role_index" on "users" ("role");
CREATE TABLE "pulse_values" ("id" integer primary key autoincrement not null, "timestamp" integer not null, "type" varchar not null, "key" text not null, "key_hash" varchar not null, "value" text not null);
CREATE INDEX "pulse_values_timestamp_index" on "pulse_values" ("timestamp");
CREATE INDEX "pulse_values_type_index" on "pulse_values" ("type");
CREATE UNIQUE INDEX "pulse_values_type_key_hash_unique" on "pulse_values" ("type", "key_hash");
CREATE TABLE "pulse_entries" ("id" integer primary key autoincrement not null, "timestamp" integer not null, "type" varchar not null, "key" text not null, "key_hash" varchar not null, "value" integer);
CREATE INDEX "pulse_entries_timestamp_index" on "pulse_entries" ("timestamp");
CREATE INDEX "pulse_entries_type_index" on "pulse_entries" ("type");
CREATE INDEX "pulse_entries_key_hash_index" on "pulse_entries" ("key_hash");
CREATE INDEX "pulse_entries_timestamp_type_key_hash_value_index" on "pulse_entries" ("timestamp", "type", "key_hash", "value");
CREATE TABLE "pulse_aggregates" ("id" integer primary key autoincrement not null, "bucket" integer not null, "period" integer not null, "type" varchar not null, "key" text not null, "key_hash" varchar not null, "aggregate" varchar not null, "value" numeric not null, "count" integer);
CREATE UNIQUE INDEX "pulse_aggregates_bucket_period_type_aggregate_key_hash_unique" on "pulse_aggregates" ("bucket", "period", "type", "aggregate", "key_hash");
CREATE INDEX "pulse_aggregates_period_bucket_index" on "pulse_aggregates" ("period", "bucket");
CREATE INDEX "pulse_aggregates_type_index" on "pulse_aggregates" ("type");
CREATE INDEX "pulse_aggregates_period_type_aggregate_bucket_index" on "pulse_aggregates" ("period", "type", "aggregate", "bucket");
